package com.kovian.finance.snapshot.api;
import com.kovian.finance.snapshot.domain.*; import com.kovian.finance.snapshot.repository.*; import com.kovian.finance.asset.repository.*; import com.kovian.finance.liability.repository.*; import com.kovian.finance.debt.repository.*; import com.kovian.finance.debt.domain.*; import com.kovian.finance.transaction.repository.*; import com.kovian.finance.transaction.domain.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/snapshots") public class SnapshotController {
final FinancialSnapshotRepository snapshots; final FinancialAssetRepository assets; final FinancialLiabilityRepository liabilities; final DebtRepository debts; final FinancialTransactionRepository transactions;
SnapshotController(FinancialSnapshotRepository s,FinancialAssetRepository a,FinancialLiabilityRepository l,DebtRepository d,FinancialTransactionRepository t){snapshots=s;assets=a;liabilities=l;debts=d;transactions=t;}
@PostMapping("/rebuild") @Transactional public FinancialSnapshot rebuild(@RequestParam UUID ownerId,@RequestParam LocalDate date){var from=date.withDayOfMonth(1).atStartOfDay().atOffset(ZoneOffset.UTC);var to=date.withDayOfMonth(date.lengthOfMonth()).plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC);BigDecimal income=BigDecimal.ZERO,expense=BigDecimal.ZERO;for(var tx:transactions.findByOwnerIdAndOccurredAtBetweenOrderByOccurredAtDesc(ownerId,from,to)){if(tx.getStatus()!=TransactionStatus.CANCELLED){if(tx.getTransactionType()==TransactionType.INCOME)income=income.add(tx.getAmount());else if(tx.getTransactionType()==TransactionType.EXPENSE)expense=expense.add(tx.getAmount());}}var a=assets.findByOwnerIdAndActiveTrue(ownerId).stream().map(com.kovian.finance.asset.domain.FinancialAsset::getCurrentValue).reduce(BigDecimal.ZERO,BigDecimal::add);var l=liabilities.findByOwnerIdAndActiveTrue(ownerId).stream().map(com.kovian.finance.liability.domain.FinancialLiability::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);l=l.add(debts.findByOwnerIdOrderByName(ownerId).stream().filter(d->d.getStatus()==DebtStatus.ACTIVE).map(Debt::getOutstandingAmount).reduce(BigDecimal.ZERO,BigDecimal::add));return snapshots.findByOwnerIdAndSnapshotDate(ownerId,date).map(existing->{return existing;}).orElseGet(()->snapshots.save(new FinancialSnapshot(ownerId,date,income,expense,a,l)));}
@GetMapping public List<FinancialSnapshot> list(@RequestParam UUID ownerId){return snapshots.findByOwnerIdOrderBySnapshotDateDesc(ownerId);}
}